installer-gui-script.script:
var BUNDLED_MACFUSE = '@MACFUSE_VERSION@';

function installedMacFUSE() {
    var b = system.files.bundleAtPath('/Library/Filesystems/macfuse.fs');
    return b ? (b.CFBundleShortVersionString || '0') : null;
}

// Install the bundled macFUSE only if it is missing or older.
function needsMacFUSE() {
    var v = installedMacFUSE();
    return v == null || system.compareVersions(v, BUNDLED_MACFUSE) < 0;
}

function installationCheck() {
    var major = parseInt(system.version.ProductVersion.split('.')[0], 10);
    if (needsMacFUSE() && major > 27) {
        my.result.type = 'Fatal';
        my.result.title = 'Please install the latest macFUSE first';
        my.result.message = 'This version of macOS is newer than the macFUSE included with NTFS RW supports. ' +
            'Install the latest macFUSE from https://macfuse.github.io, then run this installer again.';
        return false;
    }
    return true;
}
